for (const fixture of fixtures) test(fixture.style + ' source route / ' + fixture.input.rowHeights.join(',') + ' / backs ' + fixture.input.hasBackPanel, () => {
  const before = structuredClone(fixture.panels);
  const result = splitReferenceHorizontals(fixture.panels, fixture.input.width, fixture.style);
  assert.deepEqual(result.paths, fixture.paths);
  assert.deepEqual(fixture.panels, before, 'splitter must not mutate inputs');
  const volume = panels => panels.reduce((sum,p) => sum + p.w*p.h*p.d,0);
  assert.ok(Math.abs(volume(result.panels)-volume(before)) < 1e-6);
  assert.deepEqual(result.panels.filter(p => p.matType !== 'horizontalBase'), before.filter(p => p.matType !== 'horizontalBase'));
  for (const original of before.filter(p => p.matType === 'horizontalBase')) {
    const left=original.x-original.w/2, right=original.x+original.w/2;
    const pieces=result.panels.filter(p => p.matType === 'horizontalBase' && p.y === original.y && p.x-p.w/2 >= left-1e-8 && p.x+p.w/2 <= right+1e-8).sort((a,b)=>a.x-b.x);
    assert.ok(pieces.every(p => p.w > 0 && p.w <= 240+1e-8));
    assert.ok(Math.abs(pieces.reduce((sum,p)=>sum+p.w,0)-original.w)<1e-8);
    for(let i=1;i<pieces.length;i++) assert.ok(Math.abs(pieces[i-1].x+pieces[i-1].w/2-pieces[i].x+pieces[i].w/2)<1e-8, 'no visual-only gap or overlap');
  }
});

for (const style of ['grid','slant','pixel','gradient','pattern','mosaic']) {
  const styleModule=await import('../../src/lib/three/styles/'+style+'.ts');
  const calculate=styleModule['calculate'+style[0].toUpperCase()+style.slice(1)+'Panels'];
  test(style+' integration: all returned physical horizontal boards <=240 cm', () => {
    for (const width of [240,241,257,349,393,450]) for (const density of [0,17,66,99]) for (const rowHeights of [[28,28],[18,28,38]]) {
      const input={width,height:rowHeights.reduce((a,b)=>a+b,0)+2*(rowHeights.length+1),depth:32,thickness:2,density,rowHeights,numRows:rowHeights.length,hasBackPanel:false};
      const panels=calculate(input).panels;
      const horizontals=panels.filter(p=>p.matType==='horizontalBase');
      assert.ok(horizontals.length>0);
      assert.ok(horizontals.every(p=>p.w<=240+1e-8), JSON.stringify(input));
      if (width > 240) assert.ok(horizontals.length > rowHeights.length+1);
    }
  });
}
